const r = await Promise.allSettled([
  tools.exec_command({cmd:"rg -n 'DecodeHooks|DecodeHook|mapstructure|AutomaticEnv|SetEnvPrefix|BindEnv|Unmarshal' --glob '*.go' .",workdir:"/app",max_output_tokens:12000}),
  tools.exec_command({cmd:"rg --files -g '*config*' -g '*.go' | head -100",workdir:"/app",max_output_tokens:4000}),
  tools.exec_command({cmd:"rg --files -g 'AGENTS.md' -g '!vendor' -g '!**/.git/**'",workdir:"/app",max_output_tokens:2000})
]); for(const x of r) text(x.status==="fulfilled"?x.value.output:String(x.reason));

const r = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && ls -la",workdir:"/app",max_output_tokens:2000}),
  tools.exec_command({cmd:"find . -name AGENTS.md -not -path './.git/*' -print",workdir:"/app",max_output_tokens:2000}),
  tools.exec_command({cmd:"grep -RInE 'DecodeHooks|DecodeHook|mapstructure|AutomaticEnv|SetEnvPrefix|BindEnv|Unmarshal' --include='*.go' .",workdir:"/app",max_output_tokens:12000})
]); for(const x of r) text(x.status==="fulfilled"?x.value.output:String(x.reason));

